import random, itertools, sys, math

def has_cycle_of_length_at_most(edges, n_vertices, max_len):
    """Check if graph has any cycle of length <= max_len. Simple BFS/DFS approach."""
    # Build adjacency
    adj = [[] for _ in range(n_vertices)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check for cycles up to max_len using DFS with depth limit
    # For each vertex, do BFS limited depth
    for start in range(n_vertices):
        # BFS
        visited = {start: 0}
        queue = [(start, -1, 0)]
        while queue:
            node, parent, dist = queue.pop(0)
            if dist > max_len:
                continue
            for nb in adj[node]:
                if nb == parent:
                    continue
                if nb in visited:
                    if visited[nb] + dist + 1 <= max_len:
                        # cycle found
                        return True
                else:
                    visited[nb] = dist + 1
                    queue.append((nb, node, dist+1))
    return False

def is_5_colorable(edges, n_vertices):
    """Check if graph is 5-colorable using simple backtracking (small graph)."""
    adj = [[] for _ in range(n_vertices)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n_vertices

    def backtrack(v):
        if v == n_vertices:
            return True
        # Determine used colors by neighbors already colored
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(5):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def greedy_5_color(adj):
    """Try greedy coloring with 5 colors, may fail."""
    n = len(adj)
    colors = [-1]*n
    for v in range(n):
        used = {colors[nb] for nb in adj[v] if colors[nb]!=-1}
        for c in range(5):
            if c not in used:
                colors[v]=c
                break
        else:
            return None
    return colors

