# Check girth: find shortest cycle
def shortest_cycle(adj):
    n = len(adj)
    min_cycle = n+1
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[start] = 0
        queue = [start]
        while queue:
            v = queue.pop(0)
            for nb in adj[v]:
                if dist[nb] == -1:
                    dist[nb] = dist[v] + 1
                    parent[nb] = v
                    queue.append(nb)
                elif nb != parent[v]:
                    # cycle found
                    cycle_len = dist[v] + dist[nb] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

